import Compression
import CoreGraphics
import Foundation
import ImageIO
import UniformTypeIdentifiers
import os

/// Fixtures for the artwork-import suite, including the hostile ones.
///
/// The adversarial fixtures are written **by hand**, byte by byte, rather than produced by
/// `ZPDFTestingSupport`'s PDF writer. A fixture generated by a well-behaved writer is a test of
/// the writer; a contour bomb and a PNG that lies about its own size are inputs no writer in
/// this repository would ever emit, which is the point of them.
enum ArtworkFixtures {

    private static let counter = OSAllocatedUnfairLock(initialState: 0)

    static let directory: URL = {
        let url = FileManager.default.temporaryDirectory.appendingPathComponent(
            "ZPDFArtworkFixtures-\(ProcessInfo.processInfo.processIdentifier)", isDirectory: true
        )
        try? FileManager.default.createDirectory(at: url, withIntermediateDirectories: true)
        return url
    }()

    static func write(_ data: Data, name: String) throws -> URL {
        let index = counter.withLock { value -> Int in
            value += 1
            return value
        }
        let url = directory.appendingPathComponent("\(index)-\(name)", isDirectory: false)
        try data.write(to: url, options: .atomic)
        return url
    }

    /// A file of the requested size that costs nothing to create, for the size-limit test.
    /// The limit must fire before anything reads it, so its contents are never examined.
    static func sparseFile(byteCount: Int, label: String) throws -> URL {
        let url = directory.appendingPathComponent("\(label)-sparse.bin", isDirectory: false)
        try? FileManager.default.removeItem(at: url)
        guard FileManager.default.createFile(atPath: url.path, contents: nil) else {
            throw CocoaError(.fileWriteUnknown)
        }
        let handle = try FileHandle(forWritingTo: url)
        defer { try? handle.close() }
        try handle.truncate(atOffset: UInt64(byteCount))
        return url
    }

    // MARK: - Images

    /// A PNG checkerboard, which is the worst case for run merging: every cell differs from
    /// its neighbour, so nothing merges and the mosaic's own bound is the only thing holding.
    static func checkerboardPNG(edge: Int, label: String) throws -> URL {
        try png(edge: edge, label: "\(label)-checker") { x, y in
            (x + y) % 2 == 0 ? (20, 20, 20) : (240, 240, 240)
        }
    }

    /// A PNG whose top half is one colour and bottom half another, for the orientation test.
    static func halvesPNG(
        top: (UInt8, UInt8, UInt8),
        bottom: (UInt8, UInt8, UInt8),
        edge: Int,
        label: String
    ) throws -> URL {
        try png(edge: edge, label: "\(label)-halves") { _, y in y < edge / 2 ? top : bottom }
    }

    /// Renders `pixel(x, y)` — `y` measured downwards from the top — into an opaque PNG.
    static func png(
        edge: Int,
        label: String,
        pixel: (Int, Int) -> (UInt8, UInt8, UInt8)
    ) throws -> URL {
        var bytes = [UInt8](repeating: 0, count: edge * edge * 4)
        for y in 0..<edge {
            for x in 0..<edge {
                let (red, green, blue) = pixel(x, y)
                let offset = (y * edge + x) * 4
                bytes[offset] = red
                bytes[offset + 1] = green
                bytes[offset + 2] = blue
                bytes[offset + 3] = 255
            }
        }
        guard let space = CGColorSpace(name: CGColorSpace.sRGB),
              let provider = CGDataProvider(data: Data(bytes) as CFData),
              let image = CGImage(
                width: edge,
                height: edge,
                bitsPerComponent: 8,
                bitsPerPixel: 32,
                bytesPerRow: edge * 4,
                space: space,
                bitmapInfo: CGBitmapInfo(rawValue: CGImageAlphaInfo.premultipliedLast.rawValue),
                provider: provider,
                decode: nil,
                shouldInterpolate: false,
                intent: .defaultIntent
              )
        else { throw CocoaError(.fileWriteUnknown) }

        let output = NSMutableData()
        guard let destination = CGImageDestinationCreateWithData(
            output, UTType.png.identifier as CFString, 1, nil
        ) else { throw CocoaError(.fileWriteUnknown) }
        CGImageDestinationAddImage(destination, image, nil)
        guard CGImageDestinationFinalize(destination) else { throw CocoaError(.fileWriteUnknown) }
        return try write(output as Data, name: "\(label).png")
    }

    /// A tiny, entirely valid PNG whose `IHDR` claims an enormous size, with the chunk CRC
    /// recomputed so no reader rejects it as corrupt.
    ///
    /// This is the shape a decode bomb actually takes: a few hundred bytes on disk that ask
    /// the decoder for gigabytes of memory. The importer has to refuse it from the declared
    /// size, because a size measured after decoding is a size measured too late.
    static func declaredDecodeBombPNG(width: Int, height: Int, label: String) throws -> URL {
        let seed = try png(edge: 4, label: "\(label)-seed") { _, _ in (7, 7, 7) }
        var bytes = [UInt8](try Data(contentsOf: seed))

        // PNG: 8-byte signature, then the IHDR chunk — 4 length, 4 type, 13 data, 4 CRC.
        // Width and height are the first eight bytes of the data.
        let ihdrType = 8 + 4
        let ihdrData = ihdrType + 4
        guard bytes.count > ihdrData + 13 + 4,
              bytes[ihdrType] == UInt8(ascii: "I"), bytes[ihdrType + 1] == UInt8(ascii: "H")
        else { throw CocoaError(.fileReadCorruptFile) }

        func store(_ value: Int, at offset: Int) {
            let unsigned = UInt32(value)
            bytes[offset] = UInt8((unsigned >> 24) & 0xFF)
            bytes[offset + 1] = UInt8((unsigned >> 16) & 0xFF)
            bytes[offset + 2] = UInt8((unsigned >> 8) & 0xFF)
            bytes[offset + 3] = UInt8(unsigned & 0xFF)
        }
        store(width, at: ihdrData)
        store(height, at: ihdrData + 4)

        // The CRC covers the chunk type and its data, and nothing else.
        let crc = crc32(bytes[ihdrType..<(ihdrData + 13)])
        store(Int(crc), at: ihdrData + 13)

        return try write(Data(bytes), name: "\(label)-decode-bomb.png")
    }

    /// PNG's CRC-32, written out because a fixture that needs a valid checksum should not
    /// need a dependency to get one.
    static func crc32<S: Sequence>(_ bytes: S) -> UInt32 where S.Element == UInt8 {
        var table = [UInt32](repeating: 0, count: 256)
        for index in 0..<256 {
            var value = UInt32(index)
            for _ in 0..<8 {
                value = (value & 1) == 1 ? (0xEDB8_8320 ^ (value >> 1)) : (value >> 1)
            }
            table[index] = value
        }
        var crc: UInt32 = 0xFFFF_FFFF
        for byte in bytes {
            crc = table[Int((crc ^ UInt32(byte)) & 0xFF)] ^ (crc >> 8)
        }
        return crc ^ 0xFFFF_FFFF
    }

    // MARK: - The contour bomb

    /// A structurally valid, single-page PDF whose content stream paints `rectangleCount`
    /// filled rectangles.
    ///
    /// Every byte of it is legal: the cross-reference table is correct, the stream length is
    /// correct, and no reader has anything to complain about. That is what makes it the right
    /// test — the artwork limit has to hold against input that is *valid* and enormous, not
    /// only against input that is broken.
    static func contourBombPDF(rectangleCount: Int, label: String) throws -> URL {
        var content = ""
        content.reserveCapacity(rectangleCount * 14)
        content += "0 0 0 rg\n"
        for index in 0..<rectangleCount {
            let x = Double(index % 500) + 10
            let y = Double((index / 500) % 700) + 10
            content += "\(x) \(y) 1 1 re f\n"
        }
        let stream = Data(content.utf8)

        var objects: [Data] = []
        objects.append(Data("<< /Type /Catalog /Pages 2 0 R >>".utf8))
        objects.append(Data("<< /Type /Pages /Kids [3 0 R] /Count 1 >>".utf8))
        objects.append(Data("""
            << /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] \
            /Resources << >> /Contents 4 0 R >>
            """.utf8))
        var contentObject = Data("<< /Length \(stream.count) >>\nstream\n".utf8)
        contentObject.append(stream)
        contentObject.append(Data("\nendstream".utf8))
        objects.append(contentObject)

        var file = Data("%PDF-1.4\n%\u{00E2}\u{00E3}\u{00CF}\u{00D3}\n".utf8)
        var offsets: [Int] = []
        for (index, body) in objects.enumerated() {
            offsets.append(file.count)
            file.append(Data("\(index + 1) 0 obj\n".utf8))
            file.append(body)
            file.append(Data("\nendobj\n".utf8))
        }

        let xrefOffset = file.count
        file.append(Data("xref\n0 \(objects.count + 1)\n".utf8))
        file.append(Data("0000000000 65535 f \n".utf8))
        for offset in offsets {
            file.append(Data(String(format: "%010d 00000 n \n", offset).utf8))
        }
        file.append(Data("""
            trailer
            << /Size \(objects.count + 1) /Root 1 0 R >>
            startxref
            \(xrefOffset)
            %%EOF
            """.utf8))
        return try write(file, name: "\(label)-contour-bomb.pdf")
    }
}

extension ArtworkFixtures {

    /// A **completely valid** PNG that declares 900 megapixels and occupies about a hundred
    /// kilobytes on disk.
    ///
    /// This is what a decode bomb really is, and why the size check has to read the header
    /// rather than the decoded image: nothing about this file is malformed, no reader can
    /// reject it as corrupt, and decoding it asks for gigabytes. A one-bit greyscale raster of
    /// all zeros deflates to almost nothing, so the fixture is cheap to make and ruinous to
    /// open — the exact asymmetry an attacker is looking for.
    ///
    /// Built by hand: `ZPDFTestingSupport` has no image writer, and Core Graphics cannot be
    /// asked to emit an image it would first have to allocate.
    static func hugeValidPNG(width: Int, height: Int, label: String) throws -> URL {
        let rowBytes = (width + 7) / 8
        let rawByteCount = height * (rowBytes + 1)   // one filter byte per scanline

        var file = Data([137, 80, 78, 71, 13, 10, 26, 10])

        var header = Data()
        header.append(contentsOf: bigEndian(width))
        header.append(contentsOf: bigEndian(height))
        header.append(contentsOf: [1, 0, 0, 0, 0])   // 1-bit greyscale, no interlace
        file.append(chunk(type: "IHDR", payload: header))

        // zlib wrapper around raw DEFLATE, then Adler-32 of the uncompressed bytes. Every
        // byte is zero, so Adler-32 is closed form: a stays 1, b is the length.
        var stream = Data([0x78, 0x01])
        stream.append(deflateZeroes(count: rawByteCount))
        let adler = (UInt32(rawByteCount % 65521) << 16) | 1
        stream.append(contentsOf: bigEndian(Int(adler)))
        file.append(chunk(type: "IDAT", payload: stream))
        file.append(chunk(type: "IEND", payload: Data()))

        return try write(file, name: "\(label)-huge.png")
    }

    private static func bigEndian(_ value: Int) -> [UInt8] {
        let unsigned = UInt32(truncatingIfNeeded: value)
        return [
            UInt8((unsigned >> 24) & 0xFF), UInt8((unsigned >> 16) & 0xFF),
            UInt8((unsigned >> 8) & 0xFF), UInt8(unsigned & 0xFF)
        ]
    }

    private static func chunk(type: String, payload: Data) -> Data {
        var body = Data(type.utf8)
        body.append(payload)
        var out = Data(bigEndian(payload.count))
        out.append(body)
        out.append(contentsOf: bigEndian(Int(crc32(body))))
        return out
    }

    /// Raw DEFLATE of `count` zero bytes, streamed so the uncompressed form is never held.
    private static func deflateZeroes(count: Int) -> Data {
        let chunkSize = 1 << 20
        let zeroes = [UInt8](repeating: 0, count: chunkSize)
        var output = Data()
        var destination = [UInt8](repeating: 0, count: chunkSize)

        let streamPointer = UnsafeMutablePointer<compression_stream>.allocate(capacity: 1)
        defer { streamPointer.deallocate() }
        guard compression_stream_init(
            streamPointer, COMPRESSION_STREAM_ENCODE, COMPRESSION_ZLIB
        ) == COMPRESSION_STATUS_OK else { return Data() }
        defer { compression_stream_destroy(streamPointer) }

        var remaining = count
        zeroes.withUnsafeBufferPointer { source in
            while true {
                let take = Swift.min(chunkSize, remaining)
                let final = remaining <= chunkSize
                streamPointer.pointee.src_ptr = source.baseAddress!
                streamPointer.pointee.src_size = take
                remaining -= take

                var status = COMPRESSION_STATUS_OK
                repeat {
                    destination.withUnsafeMutableBufferPointer { sink in
                        streamPointer.pointee.dst_ptr = sink.baseAddress!
                        streamPointer.pointee.dst_size = sink.count
                        status = compression_stream_process(
                            streamPointer, final ? Int32(COMPRESSION_STREAM_FINALIZE.rawValue) : 0
                        )
                        output.append(sink.baseAddress!, count: sink.count - streamPointer.pointee.dst_size)
                    }
                } while status == COMPRESSION_STATUS_OK && streamPointer.pointee.src_size > 0

                if final || status != COMPRESSION_STATUS_OK { break }
            }
        }
        return output
    }
}
